    "difficulty": "Difficile",
    "type": "Jeu de plis, Défausse, Hasard",
    "goal": "Faire des levées pour éviter d'être lourdement pénalisé",
    "aliases": "La Mouche",
    "playerMin": 3,
    "playerMax": 5,
    "cardCount": 52,
    "category": "grand-groupe",
    "color": "#fb923c",
